import asyncio
from h import *
CONF="(()=>{const b=[...document.querySelectorAll('#overlayRoot .btn.primary,#overlayRoot .btn.danger')].pop();if(b){b.click();return true}return false})()"
async def main():
    async with Env() as e:
        pg=await e.page(w=1200,h=850)
        ok('shared helpers exist',await pg.evaluate("typeof MSA.multi.simple==='function'&&typeof MSA.confirmDel==='function'"))
        # ---------- Upwork proposals
        await pg.evaluate("""(()=>{const u=MSA.upwork.data();u.props=[1,2,3].map(i=>({id:'p'+i,title:'عرض '+i,client:'c'+i,status:'draft',date:'2026-11-0'+i,text:'x'}));u.ui.tab='props';MSA.save();MSA.go('upwork')})()"""); await pg.wait_for_timeout(600)
        ok('upwork rows present',await pg.evaluate("document.querySelectorAll('.uw-row').length===3"))
        await pg.click('.ms-tgl'); await pg.wait_for_timeout(200)
        ok('select mode shows bar with Select-all even at 0 selected',await pg.evaluate("!!document.querySelector('.ms-bar [data-ms=all]')&&document.querySelector('.ms-n').textContent.includes('0')"))
        await pg.click('.ms-bar [data-ms=all]'); await pg.wait_for_timeout(200)
        ok('select all selects every proposal',await pg.evaluate("MSA.multi.ids('upwork').length===3"))
        await pg.evaluate("document.querySelector('.ms-bar [data-ms=more]').click()"); await pg.wait_for_timeout(200)
        await pg.evaluate("[...document.querySelectorAll('.fm-ci')].find(b=>/تلوين/.test(b.innerText)).click()"); await pg.wait_for_timeout(200)
        await pg.evaluate("document.querySelector('.fm-ci[data-m^=\"col:#e5\"]').click()"); await pg.wait_for_timeout(400)
        ok('colour applied to frames',await pg.evaluate("MSA.upwork.data().props.every(p=>p.color==='#e5484d')&&document.querySelectorAll('.uw-row.mfr').length===3"))
        await pg.keyboard.press('Escape'); 
        await pg.click('.uw-row >> nth=0', button='right', position={'x':8,'y':8}); await pg.wait_for_timeout(250)
        ok('right-click menu on proposal',await pg.evaluate("[...document.querySelectorAll('.fm-ci')].some(b=>/حذف/.test(b.innerText))"))
        await pg.evaluate("[...document.querySelectorAll('.fm-ci')].find(b=>/حذف/.test(b.innerText)).click()"); await pg.wait_for_timeout(300)
        ok('delete asks for confirmation first',await pg.evaluate("!!document.querySelector('#overlayRoot .overlay')&&MSA.upwork.data().props.length===3"))
        await pg.evaluate("document.querySelector('#overlayRoot .btn:not(.primary):not(.danger)')&&[...document.querySelectorAll('#overlayRoot .btn')].find(b=>/إلغاء|Cancel/.test(b.innerText)).click()"); await pg.wait_for_timeout(300)
        ok('cancel keeps it',await pg.evaluate("MSA.upwork.data().props.length===3"))
        await pg.click('.uw-row >> nth=0', button='right', position={'x':8,'y':8}); await pg.wait_for_timeout(250)
        await pg.evaluate("[...document.querySelectorAll('.fm-ci')].find(b=>/حذف/.test(b.innerText)).click()"); await pg.wait_for_timeout(300)
        await pg.evaluate(CONF); await pg.wait_for_timeout(400)
        ok('confirm deletes',await pg.evaluate("MSA.upwork.data().props.length===2"))
        # ---------- Clients table
        await pg.evaluate("""(()=>{const d=MSA.clients.data();d.rows=['أ','ب','ج'].map((n,i)=>({id:'r'+i,c:{name:n,status:'نشط'}}));MSA.save();MSA.go('clients')})()"""); await pg.wait_for_timeout(600)
        await pg.click('.ms-tgl'); await pg.click('.ms-bar [data-ms=all]'); await pg.wait_for_timeout(200)
        ok('clients: select all',await pg.evaluate("MSA.multi.ids('clients').length===MSA.clients.data().rows.length"))
        await pg.evaluate("document.querySelector('.ms-bar [data-ms=more]').click()"); await pg.wait_for_timeout(200)
        await pg.evaluate("[...document.querySelectorAll('.fm-ci')].find(b=>/تلوين/.test(b.innerText)).click()"); await pg.wait_for_timeout(200)
        await pg.evaluate("document.querySelector('.fm-ci[data-m^=\"col:#3b\"]').click()"); await pg.wait_for_timeout(400)
        ok('clients: rows coloured',await pg.evaluate("MSA.clients.data().rows.every(r=>r.color==='#3b82f6')&&document.querySelectorAll('tr.mfr').length===MSA.clients.data().rows.length"))
        ok('typing in a cell still works while selecting',await pg.evaluate("!!document.querySelector('.cs-td input')"))
        await pg.evaluate("document.querySelector('.ms-bar [data-ms=a\\\\:del]').click()"); await pg.wait_for_timeout(300)
        ok('clients: bulk delete asks first',await pg.evaluate("MSA.clients.data().rows.length>0&&!!document.querySelector('#overlayRoot .overlay')"))
        await pg.evaluate(CONF); await pg.wait_for_timeout(400)
        ok('clients: confirmed bulk delete',await pg.evaluate("!MSA.clients.data().rows.some(r=>['r0','r1','r2'].includes(r.id))"))
        # ---------- Media
        await pg.evaluate("""(()=>{const m=MSA.state.media=MSA.state.media||{};m.tracks=m.tracks||[];m.lists=m.lists||[];m.videos=[1,2].map(i=>({id:'v'+i,title:'فيديو '+i,url:'https://youtu.be/abc'+i,added:Date.now()}));MSA.state.ui.mtab='video';MSA.save()})()""")
        await pg.evaluate("MSA.go('media')"); await pg.wait_for_timeout(500)
        await pg.evaluate("[...document.querySelectorAll('[data-md=tab]')].find(b=>b.dataset.id==='video').click()"); await pg.wait_for_timeout(400)
        ok('media: video cards',await pg.evaluate("document.querySelectorAll('.vc').length===2"))
        await pg.click('.ms-tgl'); await pg.click('.ms-bar [data-ms=all]'); await pg.wait_for_timeout(200)
        ok('media: select all',await pg.evaluate("MSA.multi.ids('media-video').length===2"))
        await pg.evaluate("document.querySelector('.ms-bar [data-ms=more]').click()"); await pg.wait_for_timeout(200)
        await pg.evaluate("[...document.querySelectorAll('.fm-ci')].find(b=>/تلوين/.test(b.innerText)).click()"); await pg.wait_for_timeout(200)
        await pg.evaluate("document.querySelector('.fm-ci[data-m^=\"col:#22\"]').click()"); await pg.wait_for_timeout(400)
        ok('media: videos framed with colour',await pg.evaluate("document.querySelectorAll('.vc.mfr').length===2"))
        await pg.evaluate("document.querySelector('.ms-bar [data-ms=a\\\\:del]').click()"); await pg.wait_for_timeout(300)
        ok('media: delete confirm',await pg.evaluate("MSA.state.media.videos.length===2&&!!document.querySelector('#overlayRoot .overlay')"))
        await pg.evaluate(CONF); await pg.wait_for_timeout(400)
        ok('media: confirmed delete',await pg.evaluate("MSA.state.media.videos.length===0"))
        # ---------- Learning: colour videos + select all
        await pg.evaluate("""(()=>{const L=MSA.state.learning;L.videos=[1,2].map(i=>({id:'lv'+i,folder:null,url:'https://example.com/'+i,title:'درس '+i,note:'',created:Date.now()}));L.folders=[{id:'lf1',parent:null,name:'مجلد',color:'#3b82f6',created:Date.now()}];MSA.state.ui.ltab='videos';MSA.state.ui.learnFolder=null;MSA.save();MSA.go('learn')})()"""); await pg.wait_for_timeout(700)
        await pg.click('[data-act=selmode]'); await pg.wait_for_timeout(300)
        ok('learning: select-all button appears in select mode',await pg.evaluate("!!document.querySelector('[data-act=s-all]')"))
        await pg.click('[data-act=s-all]'); await pg.wait_for_timeout(300)
        ok('learning: select all picks folders + videos',await pg.evaluate("document.querySelectorAll('.is-sel').length===3"))
        await pg.click('[data-act=s-color]'); await pg.wait_for_timeout(300)
        await pg.evaluate("document.querySelector('#sws [data-c]:not([data-c=\"\"])').click()"); await pg.wait_for_timeout(400)
        ok('learning: colour applied to videos and folders',await pg.evaluate("MSA.state.learning.videos.every(v=>v.color)&&document.querySelectorAll('.vcard.mfr').length===2"))
        # ---------- ملفاتي colour + select-all
        await pg.evaluate("""(()=>{const v=MSA.state.vault||MSA.state.files;})()""")
        # ---------- ملفاتي: colour files/folders + select all in bar
        await pg.evaluate("""(()=>{MSA.state.vault=MSA.state.vault||{items:[]};MSA.vault.newFolder('مجلد أ');MSA.vault.newFolder('مجلد ب');MSA.save();MSA.go('files')})()"""); await pg.wait_for_timeout(500)
        await pg.evaluate("(()=>{const it=MSA.state.vault&&MSA.state.vault.items||[];window.__n=it.length})()")
        await pg.evaluate("document.querySelector('.fm-card [data-fa=chk]')&&document.querySelector('.fm-card [data-fa=chk]').click()"); await pg.wait_for_timeout(250)
        ok('files: bar has select-all + colour',await pg.evaluate("!!document.querySelector('[data-fa=ball]')&&!!document.querySelector('[data-fa=bcol]')"))
        await pg.click('[data-fa=ball]'); await pg.wait_for_timeout(250)
        ok('files: select all selects every card',await pg.evaluate("document.querySelectorAll('.fm-card.sel').length===document.querySelectorAll('.fm-card').length"))
        await pg.click('[data-fa=bcol]'); await pg.wait_for_timeout(250)
        await pg.evaluate("document.querySelector('.fm-ci[data-m^=\"col:#8b\"]').click()"); await pg.wait_for_timeout(400)
        ok('files: folder colour applied',await pg.evaluate("MSA.state.vault.items.filter(x=>x.t==='d').every(x=>x.color==='#8b5cf6')"))
        ok('no page errors',not pg.errs,pg.errs)
asyncio.run(main()); summary()
